options(stringsAsFactors=FALSE);Sys.setlocale('LC_CTYPE','Spanish_Spain.utf8')
suppressPackageStartupMessages({library(dplyr);library(ggplot2)})
out<-'3. Output/two_papers_2026-09-21';rd<-function(n)read.csv(file.path(out,'tables',paste0(n,'.csv')))
export<-function(x,n)write.csv(x,file.path(out,'tables',paste0(n,'.csv')),row.names=FALSE)
met<-rd('predictive_metrics_by_repeat')
s<-met%>%group_by(model)%>%summarise(n=first(n),rmse_min=min(rmse),rmse_max=max(rmse),rmse=mean(rmse),mae=mean(mae),r2_min=min(r2),r2_max=max(r2),r2=mean(r2),.groups='drop');export(s,'predictive_metrics')
o<-readRDS(file.path(out,'reports/prediction_objects.rds'));o$metrics<-s;saveRDS(o,file.path(out,'reports/prediction_objects.rds'))
stopifnot(nrow(met)==21,nrow(o$predictions)==2156*3*7,!anyDuplicated(o$predictions[,c('id','repeat_id','model')]),all(is.finite(o$predictions$prediction)))
labs<-c(male='Male student',background='Complex background',failed='Three or more failed subjects',competence='Low basic competences',absent='Frequent unjustified absence',disruptive='Serious disciplinary problem',resources='Resource skepticism',edad='Age',level='Educational stage',antiguedad3='School tenure',meritocracia='Effort attribution',experiencia='Teaching experience',empathy='Self-reported empathy',impact='Perceived teacher impact',public='Public school',public_permanent='Reported permanent public appointment',female='Female teacher',grupos_docencia='Number of teaching groups')
saveplot<-function(p,n,w=8,h=4.5)ggsave(file.path(out,'figures',paste0(n,'.png')),p,width=w,height=h,dpi=240,bg='white')
theme_set(theme_minimal(base_size=12)+theme(panel.grid.minor=element_blank()))
saveplot(ggplot(s,aes(x=reorder(model,r2),y=100*r2))+geom_hline(yintercept=0,color='grey60')+geom_point(size=3,color='#215e70')+geom_errorbar(aes(ymin=100*r2_min,ymax=100*r2_max),width=.15)+coord_flip()+labs(x=NULL,y='Out-of-fold R-squared (%)\nPoints: mean; bars: range across three partitions'),'prediction')
a<-filter(rd('attributes'),model=='All');a$label<-labs[a$term]
saveplot(ggplot(a,aes(x=100*estimate,y=reorder(label,estimate)))+geom_vline(xintercept=0,color='grey60')+geom_errorbar(aes(xmin=100*lo,xmax=100*hi),orientation='y',width=.15)+geom_point(size=2.5,color='#215e70')+labs(x='Within-teacher coefficient (percentage points; 95% CI)',y=NULL),'attribute_effects_main')
sh<-rd('shap_oof');sh$label<-labs[sh$variable]
saveplot(ggplot(sh,aes(x=reorder(label,mean_abs_shap),y=100*mean_abs_shap))+geom_col(fill='#215e70')+coord_flip()+labs(x=NULL,y='Mean absolute out-of-fold SHAP value (percentage points)'),'shap',9,5.5)
# Validate denominators and contrast signs by direct arithmetic.
d<-readRDS(file.path(out,'reports/analysis_objects.rds'));pc<-filter(rd('policy_contrasts'),family=='Broad arms');m<-tapply(d$t$hb,d$t$arm,mean)
stopifnot(max(abs(pc$estimate-c(m['Policy']-m['Control'],m['Revelation']-m['Policy'],m['Awareness']-m['Revelation'])))<1e-10,sum(rd('flow_by_arm')$score_observed)==2705,sum(rd('flow_by_arm')$assigned)==3274,sum(d$t$n_cards)==22124)
stopifnot(abs(sum(d$t$hb*d$t$n_cards))<1e-8)
writeLines(c('All numeric validation checks passed.',paste('Validated:',Sys.time()),'2705 teachers / 22124 retained recommendations; 22006 observations identify the within-teacher slopes.','2156 complete-case teachers; three five-fold partitions; no teacher appears twice per repeat/model.','Contrasts equal direct arm-mean differences; card-weighted relative score sums to zero.','Prediction references and resource scaling fitted exclusively on training folds.','Output in-sample characterization and out-of-fold prediction refer to different reference constructions, as documented.'),file.path(out,'reports/validation.txt'))
